#!/usr/bin/env python3
"""First declared Douyin download from its observed normal Tencent store URL.

Uses the already available /usr/bin/curl, no retries, no Android interaction.
Published MD5 is a transfer check; full publisher signature verification is separate.
"""
import concurrent.futures, datetime, hashlib, json, os, pathlib, shutil, subprocess

ROOT=pathlib.Path('/home/alex/work/pocket4-launcher-official-candidates-20261106-douyin-tencent-s30')
CANDIDATES=[{'package': 'com.ss.android.ugc.aweme', 'channel_version': '41.0.0', 'landing': 'https://a.app.qq.com/o/simple.jsp?pkgname=com.ss.android.ugc.aweme', 'url': 'https://imtt.dd.qq.com/sjy.00022/sjy.00004/16891/apk/D29FFA56119C27577DCACD650998B2C0.apk?fsname=com.ss.android.ugc.aweme_41.0.0.apk', 'expected_bytes': 364363658, 'metadata_md5': 'd29ffa56119c27577dcacd650998b2c0', 'metadata_page_sha256': 'b11fb5775bf73c080784dbab9d1fcbdcfdc3d2aec42f2ff5885c030ab1350e04', 'metadata_version_code': None, 'historical_installed_version_code_reference': 400801, 'store': 'Tencent MyApp official public store; observed normal download URL, HTTPS as normal page handler', 'original_vendor_partial_untouched': True}]

def now():return datetime.datetime.now(datetime.timezone.utc).isoformat()
def digest(path):
 h=hashlib.sha256();m=hashlib.md5();count=0
 with path.open('rb') as f:
  first=f.read(4);f.seek(0)
  for b in iter(lambda:f.read(1048576),b''):h.update(b);m.update(b);count+=len(b)
 return count,h.hexdigest(),m.hexdigest(),first
def require(v,reason):
 if not v:raise RuntimeError(reason)

def fetch(c):
 row=dict(c,started_utc=now(),automatic_retry=False,installs=0,UI_actions=0,Android_reads=0,Main_lock_or_fds=0,signature_verified=False,claimed_latest_usable=False,production_ready=False)
 part=ROOT/(c['package']+'.part');headers=ROOT/(c['package']+'.headers');err=ROOT/(c['package']+'.stderr');metrics=ROOT/(c['package']+'.curl-metrics.json')
 process=None
 try:
  argv=['/usr/bin/curl','--fail','--location','--max-redirs','5','--proto','=https','--proto-redir','=https','--connect-timeout','25','--max-time','1600','--max-filesize',str(512*1024*1024),'--silent','--show-error','--user-agent','Mozilla/5.0 (Linux; Android 17) AppleWebKit/537.36','--dump-header',str(headers),'--output',str(part),'--write-out','%{json}',c['url']]
  with err.open('xb') as e,metrics.open('xb') as out:
   process=subprocess.Popen(argv,stdin=subprocess.DEVNULL,stdout=out,stderr=e)
   row['download_pid']=process.pid
   try:rc=process.wait(timeout=1620)
   except subprocess.TimeoutExpired:
    process.kill();rc=process.wait(timeout=20);row.update(timed_out=True,returncode=rc,joined=True);raise RuntimeError('CURL_SUBPROCESS_DEADLINE')
  row.update(returncode=rc,joined=True,timed_out=False)
  for label,p in [('headers',headers),('stderr',err),('curl_metrics',metrics)]:
   raw=p.read_bytes();require(len(raw)<=65536,'CURL_METADATA_OUTPUT_BOUND');row[label]={'path':str(p),'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()}
  curl=json.loads(metrics.read_bytes());row['curl']={k:curl.get(k) for k in ('http_code','url_effective','content_type','size_download','time_total','speed_download','num_redirects','num_retries','ssl_verify_result','errormsg','exitcode')}
  require(rc==0,'CURL_DOWNLOAD_FAILED')
  require(int(row['curl']['http_code'])==200 and row['curl']['num_retries']==0 and row['curl']['ssl_verify_result']==0,'SECURE_HTTP_200_REQUIRED')
  count,sha,md5,first=digest(part)
  require(first==b'PK\x03\x04','NOT_APK_ZIP')
  require(count==c['expected_bytes'] and md5==c['metadata_md5'],'PUBLISHED_STORE_TRANSFER_IDENTITY_MISMATCH')
  final=ROOT/(c['package']+'.apk');require(not final.exists(),'FINAL_PATH_EXISTS');os.rename(part,final)
  row.update(status='STAGED_PENDING_SIGNATURE_AND_IDENTITY_VERIFICATION',bytes=count,sha256=sha,actual_md5=md5,local_path=str(final),final_url=row['curl'].get('url_effective'))
 except BaseException as e:
  row.update(status='DOWNLOAD_FAILED',error_type=type(e).__name__,error=str(e)[:512],partial_preserved=part.exists())
  if part.exists():
   count,sha,md5,first=digest(part);row.update(partial_bytes=count,partial_sha256=sha,partial_md5=md5)
 row['finished_utc']=now()
 with (ROOT/(c['package']+'-download-result.json')).open('x') as f:json.dump(row,f,indent=2);f.write('\n');f.flush();os.fsync(f.fileno())
 print(json.dumps(row),flush=True);return row

def main():
 require(os.getuid()==1000 and os.geteuid()==1000,'EXACT_UNPRIVILEGED_AUTHORITY')
 require(shutil.disk_usage(ROOT.parent).free>=4*1024**3,'STAGING_SPACE_REQUIRED')
 os.umask(0o077);ROOT.mkdir(mode=0o700)
 with concurrent.futures.ThreadPoolExecutor(max_workers=1) as p:rows=list(p.map(fetch,CANDIDATES))
 report={'schema':'pocket4-official-store-declared-download-v1','installs':0,'Android_reads':0,'UI_actions':0,'Main_lock_or_fds':0,'automatic_retries':0,'candidates':rows}
 with (ROOT/'download-results.json').open('x') as f:json.dump(report,f,indent=2);f.write('\n');f.flush();os.fsync(f.fileno())
 print(json.dumps({'report':str(ROOT/'download-results.json'),'downloaded':sum(x['status'].startswith('STAGED_') for x in rows),'failed':sum(x['status']=='DOWNLOAD_FAILED' for x in rows)}),flush=True)
 return 0 if all(x['status'].startswith('STAGED_') for x in rows) else 1
if __name__=='__main__':raise SystemExit(main())
